@include('admin.shell',['title'=>'Logbook sessions'])<section class="card"><form class="filters" method="get"><input name="q" placeholder="Search student or ID" value="{{ request('q') }}"><select name="status"><option value="">Any status</option>@foreach(['ACTIVE','COMPLETED','INTERRUPTED'] as $x)<option @selected(request('status')===$x)>{{ $x }}</option>@endforeach</select><select name="computer_id"><option value="">Any computer</option>@foreach($computers as $c)<option value="{{ $c->id }}" @selected(request('computer_id')==$c->id)>{{ $c->pc_number }}</option>@endforeach</select><input type="date" name="date" value="{{ request('date') }}"><button class="small">Filter</button><a class="small" href="{{ route('admin.sessions',array_merge(request()->query(),['csv'=>1])) }}">Export CSV</a></form><div class="table-scroll"><table><tr><th>Student</th><th>ID</th><th>Grade / Subject</th><th>Reason</th><th>PC</th><th>Time in</th><th>Time out</th><th>Status</th><th>Resolution</th></tr>@foreach($sessions as $s)<tr><td>{{ $s->first_name }} {{ $s->last_name }}</td><td>{{ $s->student_id??'—' }}</td><td>{{ $s->gradeLevel->name }} / {{ $s->subject->name }}</td><td>{{ $s->usageReason->name }} {{ $s->other_reason_details }}</td><td>{{ $s->computer->pc_number }}</td><td>{{ $s->time_in->format('M j g:i A') }}</td><td>{{ $s->time_out?->format('M j g:i A')??'—' }}</td><td>{{ $s->status }}</td><td>@if($s->status==='ACTIVE'||$s->status==='INTERRUPTED')<form class="inline" method="post" action="{{ route('admin.resolve',$s) }}">@csrf<input name="resolution" required placeholder="Resolution"><button class="small">Resolve</button></form>@else{{ $s->resolution }}@endif</td></tr>@endforeach</table></div>{{ $sessions->links() }}</section></main></body></html>
